def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    slots = int(supply / WATER_REQ)
    if slots < 1:
        slots = 1

    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    opp_count = 0
    for opp in alive:
        opp_count += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 95:
                aggressive_count += 1
            if bid <= 75:
                weak_count += 1

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 85.0
        avg_prev = 85.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1
    if budget < 120:
        danger += 1

    contested = opp_count + 1 > slots

    if danger >= 4:
        bid = max(96.0, highest_prev + 3.0)
    elif danger >= 2:
        bid = max(82.0, avg_prev + 1.5)
    else:
        if slots >= 2:
            if aggressive_count >= 2:
                bid = 58.0
            elif weak_count >= 2:
                bid = 72.0
            else:
                bid = 66.0
        else:
            if contested:
                bid = max(78.0, avg_prev - 8.0)
            else:
                bid = 64.0

    if day >= 8:
        bid += 6.0
    if hp <= 2:
        bid += 10.0
    if no_water_days >= 2:
        bid += 12.0

    reserve = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = budget - reserve
    if affordable < 0:
        affordable = budget * 0.6

    if danger == 0 and highest_prev >= 110 and slots >= 2:
        bid = min(bid, 54.0)

    if budget < 90:
        bid = min(bid, budget)
    else:
        bid = min(bid, affordable, budget)

    floor_bid = 18.0
    if danger >= 2:
        floor_bid = 45.0
    if bid < floor_bid:
        bid = floor_bid
    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline budget guardrails
    # We want to avoid going broke; also ensure we can pay on multiple days.
    budget_cap = my_budget

    # Estimate required aggressiveness from yesterday bids
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # If someone was bidding very high, we target a strong but slightly conservative bid.
    # If our HP is low or we've missed water recently, we bid more.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        pressure = 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure = 0.5
    else:
        pressure = 0.35

    # Supply-based adjustment: higher supply means we can bid less to still get enough.
    # Use a normalized factor within [0,1].
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base bid target
    # When pressure is high, move toward ~0.75*DAILY_SALARY; otherwise ~0.55*DAILY_SALARY.
    base = DAILY_SALARY * (0.55 + 0.2 * pressure)

    # If supply is high, reduce bid a bit; if low, increase.
    base = base * (1.0 + 0.15 * (0.5 - supply_norm))

    # React to our own risk
    if my_hp <= 2 or my_no_water_days >= 2:
        base = base * 1.35
    elif my_hp >= 7 and my_no_water_days == 0:
        base = base * 0.9

    # Avoid overspending: if we are far from needing water, keep lower.
    # Also, do not exceed a fraction of budget to survive multiple days.
    # With 10 episode days, a conservative fraction helps.
    budget_fraction = 0.25
    if my_hp <= 3 or my_no_water_days >= 2:
        budget_fraction = 0.45
    elif my_hp >= 7:
        budget_fraction = 0.2

    hard_limit = my_budget * budget_fraction

    # If yesterday bids indicate extreme competition, slightly underbid the average-high.
    # Since bids are hidden, we use yesterday's max/avg as a proxy.
    target = base
    if highest_prev_bid > 0:
        # If opponents were bidding near/above our target, raise a bit but not to the max.
        if avg_prev_bid > target:
            target = (target + avg_prev_bid) / 2.0
        # If the max was extremely high, we try to be competitive but not match it.
        if highest_prev_bid >= DAILY_SALARY * 1.2:
            target = min(target, highest_prev_bid * 0.85)

    bid = float(target)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    bid = min(bid, hard_limit, budget_cap)

    # Ensure at least something meaningful if we have budget
    if my_budget > 0.0 and bid == 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6

    if my_hp <= 2: 
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4: 
        base_bid = DAILY_SALARY * 0.8
    elif my_hp >= 8: 
        base_bid = DAILY_SALARY * 0.45

    if my_no_water_days > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8: 
            if my_hp <= 3: 
                base_bid = max(base_bid, highest_prev_bid + 5)
            else: 
                base_bid = max(base_bid, highest_prev_bid * 1.01)
        elif highest_prev_bid < DAILY_SALARY * 0.4: 
            base_bid = min(base_bid, highest_prev_bid + 1)
        else: 
            base_bid = max(base_bid, highest_prev_bid * 1.01)

    days_remaining = EPISODE_DAYS - current_day + 1
    if days_remaining <= 3: 
        if my_hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 1.0) 
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.85)
    elif days_remaining <= 5: 
        base_bid *= 1.1 

    final_bid = max(0.0, min(my_budget, base_bid))

    if my_budget < DAILY_SALARY * 0.5 and my_hp <= 2:
        final_bid = my_budget

    return final_bid

